// Normaliza el formulario web al formato de /crm/lead.
// Convencion (autocorreccion #12): type = formulario fijo; fuente = utm_source.
// ip/ua van al motor para mejorar el match rate de Meta CAPI (skill jul-19).
const e = $input.first().json;
const b = e.body || e;
const h = e.headers || {};
const ws = (e.webhookUrl || '').includes('cicloderiqueza') ? 'cicloderiqueza' : 'atlantis';
return [{ json: {
  workspace: ws,
  email: (b.email || b.correo || '').trim(),
  nombre: b.nombre || b.name || '',
  telefono: b.telefono || b.phone || b.whatsapp || '',
  idioma: b.idioma || b.lang || 'es',
  type: b.type || 'formulario-web',
  fuente: b.utm_source || b.fuente || 'directo',
  nota: b.mensaje || b.message || '',
  ip: (h['x-forwarded-for'] || '').split(',')[0].trim(),
  ua: h['user-agent'] || ''
} }];
